def run(context):
    broken_links = []
    missing_data = []
    # Read runs for today
    runs_today = context.get_table('report.enhanced_runs', filters={'run_ts': context.inputs['run_date']})
    # Iterate through runs
    for run in runs_today:
        # Check if there are any filtered stocks for the run
        stocks = context.get_table('report.enhanced_filtered_stocks', filters={'run_id': run['run_id']})
        if not stocks:
            missing_data.append(run['run_id'])
        # If there are any links invalid, add to broken_links
        # This is a placeholder for actual logic
        if run['notes'] == 'Link broken':
            broken_links.append(run['run_id'])

    return {'broken_links': broken_links, 'missing_data': missing_data}

